import test from 'node:test';
import assert from 'node:assert/strict';
import { assertFixRequired } from '../../lib/prreview.mjs';

// Generated by eval from a real run of issueflow.
//   finding j-1 — clause rule-b44529fb broken at event e218
//   converted from an eval finding
//
// This test was RED when generated: a converged review was always declared
// unfixable, even when CI supplied the remaining work.
test('j-1: converged review permits a CI-only fix and refuses an empty fix', () => {
  const entry = { round: 1, verdict: 'converged' };
  assert.doesNotThrow(() => assertFixRequired(entry, [{ name: 'ci / issueflow', bucket: 'fail' }]));
  assert.throws(() => assertFixRequired(entry, []), /there is nothing to fix/);
  assert.doesNotThrow(() => assertFixRequired({ round: 1, verdict: 'open' }, []));
});
